use crate::aap::caps::state_read;

struct Node;

/// Keys under which the subscription list may be stored. The store cannot be
/// enumerated, so the node asks for the names it knows, in order.
const KEYS: &[&str] = &[
    "subscriptions",
    "urls",
    "feeds",
    "subscription-list",
    "subscription_list",
    "list",
];

type Chars<'a> = core::iter::Peekable<core::str::Chars<'a>>;

fn read_hex4(chars: &mut Chars) -> Option<u32> {
    let mut v: u32 = 0;
    for _ in 0..4 {
        let d = chars.next()?.to_digit(16)?;
        v = v * 16 + d;
    }
    Some(v)
}

/// Parse the remainder of a JSON string literal; the opening quote has
/// already been consumed.
fn parse_string_body(chars: &mut Chars) -> String {
    let mut out = String::new();
    while let Some(c) = chars.next() {
        match c {
            '"' => break,
            '\\' => match chars.next() {
                Some('n') => out.push('\n'),
                Some('t') => out.push('\t'),
                Some('r') => out.push('\r'),
                Some('b') => out.push('\u{8}'),
                Some('f') => out.push('\u{c}'),
                Some('u') => {
                    let hi = read_hex4(chars).unwrap_or(0xFFFD);
                    if (0xD800..0xDC00).contains(&hi) {
                        // Possible surrogate pair.
                        let mut look = chars.clone();
                        if look.next() == Some('\\') && look.next() == Some('u') {
                            if let Some(lo) = read_hex4(&mut look) {
                                if (0xDC00..0xE000).contains(&lo) {
                                    *chars = look;
                                    let cp = 0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00);
                                    out.push(char::from_u32(cp).unwrap_or('\u{FFFD}'));
                                    continue;
                                }
                            }
                        }
                        out.push('\u{FFFD}');
                    } else {
                        out.push(char::from_u32(hi).unwrap_or('\u{FFFD}'));
                    }
                }
                Some(other) => out.push(other),
                None => break,
            },
            other => out.push(other),
        }
    }
    out
}

/// Collect the string values of the first JSON array in `s`. Strings that
/// are object keys (followed by a colon) are skipped.
fn parse_json_array(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut chars: Chars = s.chars().peekable();
    let mut depth: u32 = 0;
    while let Some(c) = chars.next() {
        match c {
            '[' => depth += 1,
            ']' => {
                if depth > 0 {
                    depth -= 1;
                    if depth == 0 {
                        break;
                    }
                }
            }
            '"' => {
                let value = parse_string_body(&mut chars);
                if depth == 0 {
                    // A key or a string before the array: not an element.
                    continue;
                }
                let mut look = chars.clone();
                let mut is_key = false;
                while let Some(&n) = look.peek() {
                    if n.is_whitespace() {
                        look.next();
                    } else {
                        is_key = n == ':';
                        break;
                    }
                }
                if !is_key {
                    out.push(value);
                }
            }
            _ => {}
        }
    }
    out
}

/// Split plain text into entries: one per line or separator, with blank
/// entries and `#` comment lines ignored.
fn parse_plain(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    for line in s.split(|c| c == '\n' || c == '\r' || c == '\u{1e}') {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        for tok in line.split(|c: char| c == ',' || c.is_whitespace()) {
            let tok = tok.trim();
            if !tok.is_empty() {
                out.push(tok.to_string());
            }
        }
    }
    out
}

fn parse_value(raw: &str) -> Vec<String> {
    let t = raw.trim();
    let parsed = if t.starts_with('[') || t.starts_with('{') {
        parse_json_array(t)
    } else if t.starts_with('"') {
        let mut chars: Chars = t.chars().peekable();
        chars.next();
        let inner = parse_string_body(&mut chars);
        parse_plain(&inner)
    } else {
        parse_plain(t)
    };

    let mut urls: Vec<String> = Vec::new();
    for u in parsed {
        let u = u.trim();
        if u.is_empty() {
            continue;
        }
        if !urls.iter().any(|e| e == u) {
            urls.push(u.to_string());
        }
    }
    urls
}

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let urls = parse_value(&raw);
                if !urls.is_empty() {
                    return SubscriptionList { urls };
                }
            }
        }
        // No subscriptions are stored. The contract requires `urls` to be
        // present, and this node has no authority to invent any, so it
        // produces no output rather than one that violates the contract.
        panic!("no subscriptions found in the 'subscriptions' store");
    }
}

export!(Node);
